MAP
    NAME "SS_MAP_RURAL_LOCALIDAD_NO_INCORPORADA"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB  
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_localidad_rural_no_incorporada.log"
    DEBUG 0
    LAYER
        PROJECTION
            'init=epsg:32614'
        END #PROJECION
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_RURAL_LOCALIDAD_NO_INCORPORADA"
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "gm_localidad_rural from (select lr.id_elemento_geografico, lr.nb_localidad_rural, lr.gm_localidad_rural, lr.ds_color_elemento as color, lr.ds_color_texto as color_texto, lr.ds_color_sombra_texto as color_sombra from l_localidad_rural lr WHERE lr.fg_incorporada=0) as tmp using unique id_elemento_geografico using srid=32614"
        TYPE POLYGON
        LABELITEM "nb_localidad_rural"
        ## Sección 1
        CLASS
            NAME "El Trébol"
            EXPRESSION ('[nb_localidad_rural]'= 'EL TREBOL')
            LABEL	
                TYPE TRUETYPE
                FONT "arial"
                SIZE 13
                PARTIALS FALSE
                COLOR [color_texto]
                OUTLINECOLOR [color_sombra]
            END	
            STYLE
                OPACITY 70
                COLOR 255 81 177
            END #STYLE
            STYLE
                WIDTH 2
                OUTLINECOLOR [color]
            END #STYLE
        END #CLASS
        CLASS
            NAME "Ladrilleras del Refugio"
            EXPRESSION ('[nb_localidad_rural]'= 'LADRILLERAS DEL REFUGIO')
            LABEL	
                TYPE TRUETYPE
                FONT "arial"
                SIZE 13
                PARTIALS FALSE
                COLOR [color_texto]
                OUTLINECOLOR [color_sombra]
            END	
            STYLE
                OPACITY 70
                COLOR 81 81 81
            END #STYLE
            STYLE
                WIDTH 2
                OUTLINECOLOR [color]
            END #STYLE
        END #CLASS
        CLASS
            NAME "San Judas"
            EXPRESSION ('[nb_localidad_rural]'= 'SAN JUDAS')
            LABEL	
                TYPE TRUETYPE
                FONT "arial"
                SIZE 13
                PARTIALS FALSE
                COLOR [color_texto]
                OUTLINECOLOR [color_sombra]
            END	
            STYLE
                OPACITY 70
                COLOR 255 81 139
            END #STYLE
            STYLE
                WIDTH 2
                OUTLINECOLOR [color]
            END #STYLE
        END #CLASS
        CLASS
            NAME "Lagunillas"
            EXPRESSION ('[nb_localidad_rural]'= 'LAGUNILLAS')
            LABEL	
                TYPE TRUETYPE
                FONT "arial"
                SIZE 13
                PARTIALS FALSE
                COLOR [color_texto]
                OUTLINECOLOR [color_sombra]
            END	
            STYLE
                OPACITY 70
                COLOR 237 81 81
            END #STYLE
            STYLE
                WIDTH 2
                OUTLINECOLOR [color]
            END #STYLE
        END #CLASS
        CLASS
            NAME "Los Naranjos"
            EXPRESSION ('[nb_localidad_rural]'= 'LOS NARANJOS')
            LABEL	
                TYPE TRUETYPE
                FONT "arial"
                SIZE 13
                PARTIALS FALSE
                COLOR [color_texto]
                OUTLINECOLOR [color_sombra]
            END	
            STYLE
                OPACITY 70
                COLOR 255 194 81
            END #STYLE
            STYLE
                WIDTH 2
                OUTLINECOLOR [color]
            END #STYLE
        END #CLASS
        CLASS
            NAME "Ojo de Agua"
            EXPRESSION ('[nb_localidad_rural]'= 'OJO DE AGUA')
            LABEL	
                TYPE TRUETYPE
                FONT "arial"
                SIZE 13
                PARTIALS FALSE
                COLOR [color_texto]
                OUTLINECOLOR [color_sombra]
            END	
            STYLE
                OPACITY 70
                COLOR 255 87 81
            END #STYLE
            STYLE
                WIDTH 2
                OUTLINECOLOR [color]
            END #STYLE
        END #CLASS
        CLASS
            NAME "La Venta"
            EXPRESSION ('[nb_localidad_rural]'= 'LA VENTA')
            LABEL	
                TYPE TRUETYPE
                FONT "arial"
                SIZE 13
                PARTIALS FALSE
