            END #STYLE
        END #CLASS
        CLASS
            NAME "El Ramillete"
            EXPRESSION ('[nb_localidad_rural]'= 'EL RAMILLETE')
            LABEL	
                TYPE TRUETYPE
                FONT "arial"
                SIZE 13
                PARTIALS FALSE
                COLOR [color_texto]
                OUTLINECOLOR [color_sombra]
            END	
            STYLE
                OPACITY 70
                COLOR 255 255 0
            END #STYLE
            STYLE
                WIDTH 2
                OUTLINECOLOR [color]
            END #STYLE
        END #CLASS
        CLASS
            NAME "PreubaDatos"
            EXPRESSION ('[nb_localidad_rural]'= 'PreubaDatos')
            LABEL	
                TYPE TRUETYPE
                FONT "arial"
                SIZE 13
                PARTIALS FALSE
                COLOR [color_texto]
                OUTLINECOLOR [color_sombra]
            END	
            STYLE
                OPACITY 70
                COLOR 255 81 81
            END #STYLE
            STYLE
                WIDTH 2
                OUTLINECOLOR [color]
            END #STYLE
        END #CLASS
    END #LAYER
END #MAP
